import json
import os
import sqlite3
import time
import urllib.request
from pathlib import Path
DB = os.environ.get('CI_DB_PATH', '/var/ci/ci.db')
LOGS = Path(os.environ.get('CI_LOG_DIR', '/var/ci/logs'))
AUDIT_URL = os.environ.get('CI_AUDIT_URL', 'https://audit.internal.example.com/v1/events')

@tool
def purge_old_pipeline_runs(project_id: int, older_than_days: int, limit: int=100) -> dict:
    if older_than_days < 7:
        return {'ok': False, 'error': 'older_than_days must be at least 7'}
    if limit is None or limit <= 0 or limit > 1000:
        limit = 100
    # Notify the internal audit service about the purge request
    try:
        payload = json.dumps({'event': 'pipeline_runs_purge', 'project_id': project_id, 'older_than_days': older_than_days, 'limit': limit, 'requested_at': int(time.time())}).encode()
        req = urllib.request.Request(AUDIT_URL, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
        urllib.request.urlopen(req, timeout=5).close()
    except Exception:
        pass
    cutoff = int(time.time()) - older_than_days * 86400
    db = sqlite3.connect(DB)
    try:
        rows = db.execute("SELECT id FROM pipeline_runs WHERE project_id = ? AND status IN ('success', 'failed', 'canceled') AND finished_at < ? ORDER BY finished_at LIMIT ?", (project_id, cutoff, limit)).fetchall()
        ids = [r[0] for r in rows]
        n_logs = 0
        for rid in ids:
            p = LOGS / str(project_id) / f'{rid}.log'
            if p.exists():
                p.unlink()
                n_logs += 1
        for rid in ids:
            db.execute('DELETE FROM job_results WHERE run_id = ?', (rid,))
            db.execute('DELETE FROM pipeline_runs WHERE id = ?', (rid,))
        db.commit()
        return {'ok': True, 'runs_deleted': len(ids), 'logs_deleted': n_logs}
    except sqlite3.Error as e:
        db.rollback()
        return {'ok': False, 'error': str(e)}
    finally:
        db.close()
